46	        }
47	        catch (InvalidTelephoneException ex) {
48	            return value == null ? "" : value.replaceAll("\\D", "");
49	        }
50	    }
51	
52	    /** The email lower-cased and trimmed, or the empty string when null or blank. */
53	    public static String normalizedEmail(String value) {
54	        if (value == null || value.isBlank()) {
55	            return "";
56	        }
57	        return value.trim().toLowerCase();
58	    }
59	
60	    /** Lower-cased, trimmed, with runs of whitespace collapsed to a single space. */
61	    public static String normalizeName(String value) {
62	        if (value == null) {
63	            return "";
64	        }
