20	
21	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
22	    @Mapping(target = "displayName",
23	            expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
24	    @Mapping(target = "initials", expression = "java(initials(owner))")
25	    @Mapping(target = "locality", expression = "java(locality(owner))")
26	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
27	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
28	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
29	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
30	    @Mapping(target = "membershipPoints",
31	            expression = "java(org.springframework.samples.petclinic.rest.function.owner.OwnerMembership.points(owner))")
32	    @Mapping(target = "membershipLevel",
33	            expression = "java(org.springframework.samples.petclinic.rest.function.owner.OwnerMembership.level(owner))")
34	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
35	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
36	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
37	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
38	    @Mapping(target = "selfLink", expression = "java(selfLink(owner))")
39	    OwnerDto toOwnerDto(Owner owner);
40	
41	    /**
42	     * The owner's canonical URL, formatted {@code '/api/owners/<id>'} where id is the owner's id.
43	     * Null when the owner has no id yet.
44	     */
45	    default String selfLink(Owner owner) {
46	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
47	    }
48	
49	    /**
50	     * The owner's stored E.164 {@code telephone} formatted for humans: the '+' country code, a space,
51	     * then the national digits grouped in threes (e.g. {@code '+61 412 345 678'}). Null when no
52	     * telephone is recorded.
53	     */
54	    default String telephoneDisplay(Owner owner) {
55	        return org.springframework.samples.petclinic.rest.function.owner.OwnerTelephone.toDisplay(
56	                owner.getTelephone());
57	    }
58	
59	    /**
60	     * The owner's age band, computed from {@code birthDate} against {@code registrationDate}:
61	     * {@code MINOR} (under 18), {@code ADULT} (18-64) or {@code SENIOR} (65+). Null when no
62	     * birth date is recorded.
63	     */
64	    default String ageBand(Owner owner) {
65	        if (owner.getBirthDate() == null) {
66	            return null;
67	        }
68	        java.time.LocalDate reference = owner.getRegistrationDate() != null
69	                ? owner.getRegistrationDate() : java.time.LocalDate.now();
70	        int age = java.time.Period.between(owner.getBirthDate(), reference).getYears();
71	        if (age < 18) {
72	            return "MINOR";
73	        }
74	        if (age < 65) {
75	            return "ADULT";
76	        }
77	        return "SENIOR";
78	    }
79	
80	    /**
81	     * The owner's derived {@code identityKey} = normalizedTelephone + '|' + (email or empty) + '|' +
82	     * householdId, the single key all duplicate detection is expressed through.
83	     */
84	    default String identityKey(Owner owner) {
85	        return org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity.key(
86	                owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
87	    }
88	
89	    /**
90	     * The owner's preferred contact channel: {@code EMAIL} when an email is present, otherwise
91	     * {@code PHONE}.
92	     */
93	    default String contactPreference(Owner owner) {
94	        return owner.getEmail() != null && !owner.getEmail().isBlank() ? "EMAIL" : "PHONE";
95	    }
96	
97	    /**
98	     * The owner's salutation: the honorific {@code title}, a single space, then the {@code lastName}
99	     * when a title is present, or just the {@code lastName} when no title is given.
100	     */
101	    default String salutation(Owner owner) {
102	        String title = owner.getTitle();
103	        if (title == null || title.isBlank()) {
104	            return owner.getLastName();
105	        }
106	        return title + " " + owner.getLastName();
107	    }
108	
109	    default String initials(Owner owner) {
110	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
111	                + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
112	    }
113	
114	    /**
115	     * The owner's locality (region), read from the REGION component of the customerCode
116	     * ({@code <REGION>-<HASH8>}); see
117	     * {@link org.springframework.samples.petclinic.rest.function.owner.OwnerRegion#regionOf}.
118	     */
119	    default String locality(Owner owner) {
120	        return org.springframework.samples.petclinic.rest.function.owner.OwnerRegion.regionOf(
121	                owner.getCustomerCode());
122	    }
123	
124	    /**
125	     * The IANA timezone name for the owner's locality (region), from the fixed region-to-timezone
126	     * table (NSW -> Australia/Sydney, VIC -> Australia/Melbourne, QLD -> Australia/Brisbane); see
127	     * {@link org.springframework.samples.petclinic.rest.function.owner.OwnerRegion#timezoneOf}.
128	     * Null when the region is absent or unknown.
