3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import net.officefloor.plugin.variable.Out;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.DisposableEmailException;
9	import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;
10	import org.springframework.samples.petclinic.rest.escalation.InvalidPostcodeException;
11	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
12	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
13	import org.springframework.web.bind.annotation.RequestBody;
14	
15	/**
16	 * First step of {@code POST /api/owners}: rejects a request that is missing or blank in any of
17	 * firstName, lastName, address, city or telephone. A whitespace-only value counts as blank, which
18	 * bean validation alone does not catch for the pattern-less address/city fields, so the check is
19	 * explicit here. The address is normalized first (see {@link OwnerAddress}) and the required-field
20	 * check rejects an address that is blank after normalization; the normalized value is written back
21	 * so it is stored, returned and used for every later address comparison. The telephone is then
22	 * normalized to E.164 form (see {@link OwnerTelephone}); the
23	 * normalized value is written back so it is stored and returned, and a value that cannot form valid
24	 * E.164 is a 400. The
25	 * optional email, when present, must be a syntactically valid address and is normalized to lower
26	 * case; a present-but-invalid email is a 400. On success it republishes the body for {@link BuildOwner}.
27	 */
28	public class ValidateOwnerFields {
29	
30	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
31	            throws MissingOwnerFieldsException, InvalidTelephoneException, InvalidEmailException,
32	            DisposableEmailException, InvalidPostcodeException {
33	        // Normalize whichever address fields are supplied, preferring the structured form. The stored,
34	        // returned 'address' is the composed value (normalized addressLine1, plus a space and the
35	        // normalized addressLine2 when present), falling back to the flat 'address'.
36	        String line1 = OwnerAddress.normalize(request.getAddressLine1());
37	        String line2 = OwnerAddress.normalize(request.getAddressLine2());
38	        request.setAddressLine1(line1.isEmpty() ? null : line1);
39	        request.setAddressLine2(line2.isEmpty() ? null : line2);
40	        request.setAddress(OwnerAddress.compose(request.getAddressLine1(),
41	                request.getAddressLine2(), request.getAddress()));
42	        List<String> missing = new ArrayList<>();
43	        require("firstName", request.getFirstName(), missing);
44	        require("lastName", request.getLastName(), missing);
45	        // Valid when an address is supplied in EITHER form; the composed value is blank only when both
46	        // the structured addressLine1 and the flat address are missing.
47	        require("address", request.getAddress(), missing);
48	        require("city", request.getCity(), missing);
49	        require("telephone", request.getTelephone(), missing);
50	        if (!missing.isEmpty()) {
51	            throw new MissingOwnerFieldsException(missing);
52	        }
53	        request.setTelephone(OwnerTelephone.toE164(request.getTelephone()));
54	        request.setEmail(OwnerEmail.normalize(request.getEmail()));
55	        request.setPostcode(Postcode.normalize(request.getPostcode(), request.getCity()));
56	        validated.set(request);
57	    }
58	
59	    private static void require(String field, String value, List<String> missing) {
60	        if (value == null || value.isBlank()) {
61	            missing.add(field);
62	        }
63	    }
64	}
